cd /workspace; cat > /tmp/fp_test.php <<'PHP'
<?php
require '/var/www/html/vendor/autoload.php';
require '/var/www/html/config/web.config.php';
require '/var/www/html/config/web.config.local.php';
Dsl\App\Page::$config = array_replace_recursive($config, $configLocal);

// show field names used by copyMassnahmen for the dump's 2024 plan (predecessor 2023 has fields)
$f24 = Dsl\App\Entities\FachPlanung::getFormFieldSqlNames(2024, 'massnahme');
$t24 = Dsl\App\Entities\FachPlanung::getFormFieldSqlNames(2024, 'teilmassnahme');
echo "massnahme fields for 2024: " . count($f24) . "\n";
echo "teilmassnahme fields for 2024: " . count($t24) . "\n";
$f27 = Dsl\App\Entities\FachPlanung::getFormFieldSqlNames(2027, 'massnahme');
echo "massnahme fields for 2027: " . count($f27) . "\n";

// Build the exact SQL copyMassnahmen would build for target 2024 from prev 2023, and trial-run+rollback
$moreFields = implode(', ', $f24);
$insertFields = 'Ident,lft_nummer,fk_gesamtplan,fk_dienststelle,status_markiert,redakteur_level,fk_kopie_von,full_text,' . $moreFields;
$selectFields = "Ident,lft_nummer,2024,fk_dienststelle,'kopiert',4,id,full_text," . $moreFields;
$sql = "INSERT INTO massnahme ($insertFields) SELECT $selectFields FROM massnahme WHERE deleted = 0 AND aenderungs_antrag = 0 AND fk_gesamtplan=2023 and fk_dienststelle='0201'";
$db = Dsl\App\Page::db();
$db->beginTransaction();
$st = $db->prepare($sql);
$ok = $st->execute();
echo "trial copy for plan with fields (2023->2024) execute=" . var_export($ok,true) . " rows=" . $st->rowCount() . "\n";
$db->rollBack();

// Now the empty-fields case (target 2027 from prev 2026)
$moreFields27 = implode(', ', $f27);
$insertFields27 = 'Ident,lft_nummer,fk_gesamtplan,fk_dienststelle,status_markiert,redakteur_level,fk_kopie_von,full_text,' . $moreFields27;
$selectFields27 = "Ident,lft_nummer,2027,fk_dienststelle,'kopiert',4,id,full_text," . $moreFields27;
$sql27 = "INSERT INTO massnahme ($insertFields27) SELECT $selectFields27 FROM massnahme WHERE deleted = 0 AND aenderungs_antrag = 0 AND fk_gesamtplan=2026 and fk_dienststelle='9901'";
$db->beginTransaction();
$st2 = $db->prepare($sql27);
$ok2 = @$st2->execute();
echo "trial copy for plan without fields (2026->2027) execute=" . var_export($ok2,true) . "\n";
echo "errorInfo: " . json_encode($st2->errorInfo()) . "\n";
$db->rollBack();
PHP
docker cp /tmp/fp_test.php ddev-tfm-fachplanung-web:/tmp/fp_test.php
docker exec ddev-tfm-fachplanung-web bash -c 'cd /var/www/html && php -dxdebug.mode=off /tmp/fp_test.php' 2>&1 | tail -20
